package cn.mop.persistence;
import cn.mop.domain.*;
import cn.mop.domain.capacity.*;
import cn.mop.domain.capacity.CapacityScenarioRepository.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.math.*;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.junit.jupiter.api.Assertions.*;
import static cn.mop.persistence.PostgresManualAssetMetadataIntegrationTest.*;
/** Actual V16 PG/runtime-role transactions. Clearly synthetic labels; no measured capacity claims. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresCapacityScenarioIntegrationTest {
    static PostgresCapacityScenarioRepository scenarios;
    @BeforeAll static void ready()throws SQLException{connect();scenarios=new PostgresCapacityScenarioRepository(pool,platform,mapper);assertEquals(List.of(),scenarios.readinessProblems());}
    @AfterAll static void finish(){close();}
    static Access scope(String who){return scope(who,TENANT);}
    static Access scope(String who,String tenant){return new Access(who,tenant,platform.membership(who,tenant).orElseThrow().permissionVersion(),UUID.randomUUID().toString());}
    static CapacityScenarioDraft draft(String label,boolean known){var c=known?new CapacityCalculation(new CapacityEstimate.Inputs(new BigInteger("9007199254740993"),BigInteger.ONE,new BigDecimal("10.000"),2,new BigDecimal("80.00"),new BigDecimal("0.50"),3,new BigDecimal("0.25")),new CapacityEstimate.Model("SYNTHETIC-v1",new BigDecimal("128"),new BigDecimal("60")),null):new CapacityCalculation(null,null,null);return new CapacityScenarioDraft(label," 明确合成方案\n原文保留 ",c,null);}
    static String label(){return "CAPACITY-DRAFT-"+UUID.randomUUID();}
    static Stored create(CapacityScenarioDraft value){var a=scope(admin);return (Stored)platform.idempotentAuthorized(a.actorId(),a.tenantId(),"POST /integration/capacity-drafts",UUID.randomUUID().toString(),"a".repeat(64),a.permissionVersion(),()->scenarios.authorizeCreate(a),()->scenarios.create(a,0,value));}
    static Map<String,Object> receipt(Stored value){return Map.of("id",value.id(),"tenant_id",value.tenantId(),"version",value.version(),"calculation",value.draft().calculation().wire(),"calculation_sha256",value.calculationSha256(),"snapshot_sha256",value.snapshotSha256());}
    static long auditCount(String id)throws SQLException{try(var c=pool.getConnection();var s=c.prepareStatement("SELECT count(*) FROM public.mop_audit WHERE payload->>'action'='capacity.scenario.create' AND payload->>'resource_id'=?")){s.setString(1,id);try(var r=s.executeQuery()){r.next();return r.getLong(1);}}}
    @Test void unknownProposalCommitsOnlyDraftWithRealTimestampAndDurableReopen()throws Exception{var input=draft(label(),false);Instant before=Instant.now().minusSeconds(1);Stored saved=create(input);assertEquals(input,saved.draft());assertEquals(1,saved.version());assertEquals(admin,saved.actorId());assertEquals(TENANT,saved.tenantId());assertTrue(saved.recordedAt().isAfter(before));assertEquals("DRAFT",saved.draft().lifecycleStatus());assertFalse(saved.draft().effective());assertNull(saved.snapshot().capacity().outputs());assertEquals("NOT_PROVIDED",saved.draft().benchmarkVerification());assertTrue(saved.calculationSha256().matches("[0-9a-f]{64}"));assertTrue(saved.snapshotSha256().matches("[0-9a-f]{64}"));assertEquals(1,auditCount(saved.id()));assertEquals(saved,new PostgresCapacityScenarioRepository(pool,new PostgresPlatformRepository(pool,mapper),mapper).get(scope(admin),saved.id()));}
    @Test void knownInputsKeepArbitraryPrecisionScaleAndUnverifiedBaselineReference(){var original=draft(label(),true);var input=new CapacityScenarioDraft(original.label(),original.note(),original.calculation(),new CapacityScenarioDraft.BenchmarkReference("document-ref:SYNTHETIC-baseline","合成引用","A".repeat(64)));Stored saved=create(input);assertEquals(input,saved.draft());assertEquals(original.calculation().snapshot(),saved.snapshot());assertEquals("REFERENCE_ONLY_UNVERIFIED",saved.draft().benchmarkVerification());assertFalse(saved.draft().productionCapacityVerified());assertFalse(saved.draft().pocExecuted());assertEquals("10.000",((Map<?,?>)saved.draft().calculation().wire().get("inputs")).get("interval_seconds"));assertEquals("9007199254740993",((Map<?,?>)saved.draft().calculation().wire().get("inputs")).get("hosts"));}
    @Test void originalIdempotentReceiptSurvivesOtherDraftsWithoutDuplicateAudit()throws Exception{var a=scope(admin);String key=UUID.randomUUID().toString(),route="POST /integration/capacity-replay";var input=draft(label(),true);Object first=platform.idempotentAuthorized(admin,TENANT,route,key,"a".repeat(64),a.permissionVersion(),()->scenarios.authorizeCreate(a),()->receipt(scenarios.create(a,0,input)));create(draft(label(),false));Object replay=platform.idempotentAuthorized(admin,TENANT,route,key,"a".repeat(64),a.permissionVersion(),()->scenarios.authorizeCreate(a),()->{throw new AssertionError("Original request must not insert again");});assertEquals(json(first),json(replay));String id=(String)((Map<?,?>)first).get("id");assertEquals(1,auditCount(id));assertEquals(1,scenarios.list(a,input.label(),101,null,null).size());assertEquals("IDEMPOTENCY_CONFLICT",assertThrows(DomainException.class,()->platform.idempotentAuthorized(admin,TENANT,route,key,"b".repeat(64),a.permissionVersion(),()->scenarios.authorizeCreate(a),()->null)).code);}
    @Test void padminAndProtectedTransactionAreRequiredForCreateAndReads(){var value=draft(label(),false);assertThrows(IllegalStateException.class,()->scenarios.create(scope(admin),0,value));assertThrows(IllegalStateException.class,()->scenarios.authorizeCreate(scope(admin)));Stored saved=create(value);for(String who:List.of(engineer,viewer,tadmin)){var a=scope(who);assertEquals(403,assertThrows(DomainException.class,()->scenarios.get(a,saved.id())).status);assertEquals(403,assertThrows(DomainException.class,()->scenarios.list(a,"",10,null,null)).status);assertEquals(403,assertThrows(DomainException.class,()->platform.idempotentAuthorized(who,TENANT,"POST /integration/capacity-denied",UUID.randomUUID().toString(),"a".repeat(64),a.permissionVersion(),()->scenarios.authorizeCreate(a),()->scenarios.create(a,0,value))).status);}}
    @Test void staleMembershipGuardRunsBeforeCachedReceipt(){var a=scope(admin);String key=UUID.randomUUID().toString(),route="POST /integration/capacity-stale";platform.idempotentAuthorized(admin,TENANT,route,key,"a".repeat(64),a.permissionVersion(),()->scenarios.authorizeCreate(a),()->receipt(scenarios.create(a,0,draft(label(),false))));var stale=new Access(a.actorId(),a.tenantId(),a.permissionVersion()+1,a.traceId());assertEquals(401,assertThrows(DomainException.class,()->platform.idempotentAuthorized(admin,TENANT,route,key,"a".repeat(64),a.permissionVersion(),()->scenarios.authorizeCreate(stale),()->null)).status);assertEquals(401,assertThrows(DomainException.class,()->scenarios.list(stale,"",10,null,null)).status);}
    @Test void crossTenantIdsAreHiddenAndListsNeverJoinOtherScope(){var other=scope(admin,OTHER);String name=label();Stored foreign=(Stored)platform.idempotentAuthorized(admin,OTHER,"POST /integration/capacity-other",UUID.randomUUID().toString(),"a".repeat(64),other.permissionVersion(),()->scenarios.authorizeCreate(other),()->scenarios.create(other,0,draft(name,false)));assertEquals(404,assertThrows(DomainException.class,()->scenarios.get(scope(admin),foreign.id())).status);assertTrue(scenarios.list(scope(admin),name,10,null,null).isEmpty());assertEquals(foreign,scenarios.get(other,foreign.id()));}
    @Test void literalUnicodeLabelSearchDoesNotInspectNotesOrTreatWildcardsAsPatterns(){String marker="Ä%_"+UUID.randomUUID();Stored saved=create(draft(marker,true));assertEquals(List.of(saved),scenarios.list(scope(admin),marker.replace('Ä','ä'),10,null,null));assertTrue(scenarios.list(scope(admin),marker+"' OR '1'='1",10,null,null).isEmpty());assertTrue(scenarios.list(scope(admin),saved.id(),10,null,null).isEmpty());assertTrue(scenarios.list(scope(admin),"明确合成方案",10,null,null).isEmpty());}
    @Test void boundedCreationKeysetPagesTwoTwoOneWithoutDuplicates(){String marker=label();for(int i=0;i<5;i++)create(draft(marker+"-"+i,false));var a=scope(admin);var all=scenarios.list(a,marker,101,null,null);assertEquals(5,all.size());List<String> seen=new ArrayList<>();Instant before=null;String id=null;for(int page=0;page<3;page++){var rows=scenarios.list(a,marker,2,before,id);assertEquals(page<2?2:1,rows.size());rows.forEach(v->seen.add(v.id()));var last=rows.get(rows.size()-1);before=last.recordedAt();id=last.id();}assertEquals(all.stream().map(Stored::id).toList(),seen);assertEquals(5,new HashSet<>(seen).size());assertTrue(scenarios.list(a,marker,2,before,id).isEmpty());}
    @Test void downstreamFailureRollsBackDraftAuditAndReceiptAndAllowsExplicitRetry()throws Exception{var a=scope(admin);String key=UUID.randomUUID().toString(),route="POST /integration/capacity-rollback",name=label();AtomicReference<String> failedId=new AtomicReference<>();assertThrows(IllegalStateException.class,()->platform.idempotentAuthorized(admin,TENANT,route,key,"a".repeat(64),a.permissionVersion(),()->scenarios.authorizeCreate(a),()->{var saved=scenarios.create(a,0,draft(name,false));failedId.set(saved.id());throw new IllegalStateException("Synthetic downstream failure");}));assertTrue(scenarios.list(a,name,10,null,null).isEmpty());assertEquals(0,auditCount(failedId.get()));assertEquals(404,assertThrows(DomainException.class,()->scenarios.get(a,failedId.get())).status);Object retry=platform.idempotentAuthorized(admin,TENANT,route,key,"b".repeat(64),a.permissionVersion(),()->scenarios.authorizeCreate(a),()->receipt(scenarios.create(a,0,draft(name,true))));assertNotEquals(failedId.get(),((Map<?,?>)retry).get("id"));assertEquals(1,scenarios.list(a,name,10,null,null).size());}
    @Test void concurrentSameRequestAcrossIndependentConnectionsCreatesOneDraftAndAudit()throws Exception{var a=scope(admin);String name=label(),key=UUID.randomUUID().toString(),route="POST /integration/capacity-concurrent";var ready=new CountDownLatch(2);var start=new CountDownLatch(1);var executor=Executors.newFixedThreadPool(2);AtomicInteger writes=new AtomicInteger();try{List<Future<Object>> futures=new ArrayList<>();for(int i=0;i<2;i++)futures.add(executor.submit(()->{var p=new PostgresPlatformRepository(pool,mapper);var repo=new PostgresCapacityScenarioRepository(pool,p,mapper);ready.countDown();assertTrue(start.await(10,TimeUnit.SECONDS));return p.idempotentAuthorized(admin,TENANT,route,key,"a".repeat(64),a.permissionVersion(),()->repo.authorizeCreate(a),()->{writes.incrementAndGet();return receipt(repo.create(a,0,draft(name,true)));});}));assertTrue(ready.await(10,TimeUnit.SECONDS));start.countDown();Object one=futures.get(0).get(15,TimeUnit.SECONDS),two=futures.get(1).get(15,TimeUnit.SECONDS);assertEquals(json(one),json(two));assertEquals(1,writes.get());var rows=scenarios.list(a,name,10,null,null);assertEquals(1,rows.size());assertEquals(1,auditCount(rows.get(0).id()));}finally{executor.shutdownNow();}}
    @Test void independentExplicitRequestsCreateDistinctImmutableProposalsNotSilentUpdates()throws Exception{var value=draft(label(),false);Stored one=create(value),two=create(value);assertNotEquals(one.id(),two.id());assertEquals(1,one.version());assertEquals(1,two.version());assertEquals(one,scenarios.get(scope(admin),one.id()));assertEquals(2,scenarios.list(scope(admin),value.label(),10,null,null).size());assertEquals(1,auditCount(one.id()));assertEquals(1,auditCount(two.id()));}
    @Test void successfulRepeatedReadsLeaveAuditTailAndStoredFactsUntouched()throws Exception{Stored saved=create(draft(label(),true));long before;try(var c=pool.getConnection();var s=c.createStatement();var r=s.executeQuery("SELECT COALESCE(max(sequence),0) FROM public.mop_audit")){r.next();before=r.getLong(1);}for(int i=0;i<3;i++){assertEquals(saved,scenarios.get(scope(admin),saved.id()));assertEquals(List.of(saved),scenarios.list(scope(admin),saved.draft().label(),10,null,null));}try(var c=pool.getConnection();var s=c.createStatement();var r=s.executeQuery("SELECT COALESCE(max(sequence),0) FROM public.mop_audit")){r.next();assertEquals(before,r.getLong(1));}}
    @Test void unpairedCursorInvalidLabelsAndUnboundedLimitsFailClosed(){var a=scope(admin);for(int limit:new int[]{0,102})assertEquals(400,assertThrows(DomainException.class,()->scenarios.list(a,"",limit,null,null)).status);for(String query:Arrays.asList(null,"x\n","😀".repeat(101)))assertEquals(400,assertThrows(DomainException.class,()->scenarios.list(a,query,10,null,null)).status);assertEquals(400,assertThrows(DomainException.class,()->scenarios.list(a,"",10,Instant.EPOCH,null)).status);assertEquals(400,assertThrows(DomainException.class,()->scenarios.list(a,"",10,null,UUID.randomUUID().toString())).status);assertEquals(400,assertThrows(DomainException.class,()->scenarios.list(a,"",10,Instant.ofEpochSecond(0,1),UUID.randomUUID().toString())).status);assertEquals(400,assertThrows(DomainException.class,()->scenarios.get(a,"not-an-id")).status);}
    @Test void realStoredRowsWithForgedArithmeticOrNumericInputTypesAreRejectedAndRolledBack()throws Exception{
        for(boolean forgedArithmetic:List.of(true,false))try(var c=pool.getConnection()){c.setAutoCommit(false);var value=draft(label(),true);ObjectNode calculation=mapper.valueToTree(value.calculation().wire()),snapshot=mapper.valueToTree(value.calculation().snapshot());if(forgedArithmetic)((ObjectNode)snapshot.get("capacity").get("outputs")).put("pools",999999);else ((ObjectNode)calculation.get("inputs")).put("hosts",10);String id=UUID.randomUUID().toString();
            try(var s=c.prepareStatement("WITH material AS (SELECT ?::jsonb c,?::jsonb s) INSERT INTO public.mop_capacity_scenario_draft(id,tenant_id,actor_id,label,note,calculation,calculation_sha256,snapshot,snapshot_sha256) SELECT ?::uuid,?::uuid,?::uuid,'SYNTHETIC-ROLLBACK-CORRUPT','Synthetic rollback only',c,encode(sha256(convert_to(c::text,'UTF8')),'hex'),s,encode(sha256(convert_to(s::text,'UTF8')),'hex') FROM material")){s.setString(1,calculation.toString());s.setString(2,snapshot.toString());s.setString(3,id);s.setString(4,TENANT);s.setString(5,admin);assertEquals(1,s.executeUpdate());}
            try(var s=c.prepareStatement(PostgresCapacityScenarioRepository.select()+" WHERE id=?::uuid")){s.setString(1,id);try(var r=s.executeQuery()){assertTrue(r.next());assertEquals(503,assertThrows(DomainException.class,()->scenarios.stored(r,scope(admin))).status);}}c.rollback();
        }
    }
    @Test void creationOnlyExpectedVersionCannotPretendToOverwriteAnExistingProposal(){var a=scope(admin);String name=label();for(long expected:new long[]{-1,1,Long.MAX_VALUE})assertEquals(400,assertThrows(DomainException.class,()->platform.idempotentAuthorized(admin,TENANT,"POST /integration/capacity-create-version",UUID.randomUUID().toString(),"a".repeat(64),a.permissionVersion(),()->scenarios.authorizeCreate(a),()->scenarios.create(a,expected,draft(name,false)))).status);assertTrue(scenarios.list(a,name,10,null,null).isEmpty());}

}
